-- Local candidate only. Remote project identity and authorization require a separate gate.
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL search_path=pg_catalog,pg_temp;
SET LOCAL statement_timeout='45s';
SET LOCAL lock_timeout='2s';
DO $$ BEGIN IF current_database()<>'postgres' OR current_user<>'postgres' OR (SELECT array_agg(signature) FROM artecna_distruzione.hard_delete_catalog_expected) IS DISTINCT FROM ARRAY[artecna_distruzione.hard_delete_catalog()] THEN RAISE EXCEPTION 'STOP_IDENTITA_O_HARD_DELETE';END IF;END $$;
DO $$ BEGIN IF to_regclass('artecna_contabilita.bluenext_fonti') IS NOT NULL OR to_regclass('artecna_contabilita.bluenext_evidenze') IS NOT NULL OR to_regclass('artecna_contabilita.bluenext_lotti') IS NOT NULL OR to_regprocedure('public.conferma_bluenext_integrato(uuid,jsonb,jsonb,text,boolean,boolean)') IS NOT NULL THEN RAISE EXCEPTION 'STOP_COLLISIONE_BLUENEXT'; END IF;IF to_regprocedure('public.associa_fattura_bluenext(uuid,text,text[],text,boolean)') IS NULL OR to_regprocedure('public.riconcilia_acconto_fattura(uuid,uuid,uuid,uuid,jsonb,jsonb,text,text,boolean,jsonb)') IS NULL OR to_regprocedure('artecna_notifiche.riconcilia_acconto_fiscale(uuid,timestamp with time zone)') IS NULL OR (SELECT encode(sha256(convert_to(replace(prosrc,E'\r\n',E'\n'),'UTF8')),'hex') FROM pg_proc WHERE oid=to_regprocedure('artecna_contabilita.documento_riconciliazione(uuid,jsonb)')) IS DISTINCT FROM 'd96d9e315c4ba14c8c0282b090116cee5a45b1492abd8478a3406365f750abd1' THEN RAISE EXCEPTION 'STOP_DIPENDENZA_BLUENEXT';END IF;END $$;
WITH rel AS(SELECT unnest(ARRAY['public.cantieri','public.preventivi_cantiere','public.sal_lavorazioni','public.acconti_cantiere','public.fatture_emesse','public.fatture_fornitori','public.fatture_fornitori_righe','public.utenti_impresa','public.utenti_cantiere','artecna_contabilita.attribuzioni_clienti','artecna_contabilita.incassi_lordi_clienti','artecna_contabilita.quote_lorde_clienti','artecna_contabilita.imputazioni_acconti','artecna_contabilita.acconti_fiscali','artecna_contabilita.fatture_sdi','artecna_contabilita.storni_acconti','artecna_notifiche.evento_notificabile','artecna_notifiche.notifica']) AS name), digests AS (SELECT name,query_to_xml(format('SELECT count(*) AS rows,encode(sha256(convert_to(coalesce(string_agg((CASE WHEN %L=''public.fatture_emesse'' THEN to_jsonb(t)||jsonb_build_object(''xml_testo'',coalesce(to_jsonb(t)->''xml_testo'',''null''::jsonb)) ELSE to_jsonb(t) END)::text,E''\n'' ORDER BY to_jsonb(t)::text COLLATE "C"),''''),''UTF8'')),''hex'') AS sha256 FROM %s t',name,name::regclass),false,false,'') AS value FROM rel) SELECT jsonb_build_object('marker','ARTECNA_BLUENEXT_INTEGRATO_PRECHECK_READONLY','readonly',current_setting('transaction_read_only'),'fingerprints',jsonb_object_agg(name,jsonb_build_object('rows',(xpath('/table/row/rows/text()',value))[1]::text::bigint,'sha256',(xpath('/table/row/sha256/text()',value))[1]::text)),'migration_registry_modified',false,'rollback_proven_by_row',false) AS evidence FROM digests;
ROLLBACK;
